        乙.close();
    }

    static void 守着一位(Socket 客) {
        try {
            BufferedReader 读 = 读者(客);
            PrintWriter 写 = 写手(客);
            String 名字 = 读.readLine();
            屋里.add(写);
            写.println("欢迎 " + 名字);
            String 一句;
            while ((一句 = 读.readLine()) != null) {
